     1→
     2→-- Enable pgvector extension FIRST
     3→CREATE EXTENSION IF NOT EXISTS vector WITH SCHEMA extensions;
     4→
     5→-- =============================================
     6→-- INSTANT RESUME RANKER — FULL DATABASE SCHEMA
     7→-- =============================================
     8→
     9→-- 1. ENUM for roles
    10→CREATE TYPE public.app_role AS ENUM ('admin', 'user');
    11→
    12→-- 2. PROFILES TABLE
    13→CREATE TABLE public.profiles (
    14→  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    15→  user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL UNIQUE,
    16→  plan TEXT DEFAULT 'free',
    17→  credits INTEGER NOT NULL DEFAULT 0,
    18→  inbox_email TEXT UNIQUE,
    19→  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    20→  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
    21→);
    22→
    23→-- 3. USER_ROLES TABLE
    24→CREATE TABLE public.user_roles (
    25→  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    26→  user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL,
    27→  role app_role NOT NULL DEFAULT 'user',
    28→  UNIQUE (user_id, role)
    29→);
    30→
    31→-- 4. PLANS TABLE
    32→CREATE TABLE public.plans (
    33→  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    34→  name TEXT NOT NULL,
    35→  price NUMERIC(10,2) NOT NULL DEFAULT 0,
    36→  credits INTEGER NOT NULL DEFAULT 0,
    37→  billing_type TEXT NOT NULL DEFAULT 'monthly',
    38→  active BOOLEAN NOT NULL DEFAULT true,
    39→  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
    40→);
    41→
    42→-- 5. CREDIT_PACKS TABLE
    43→CREATE TABLE public.credit_packs (
    44→  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    45→  name TEXT NOT NULL,
    46→  price NUMERIC(10,2) NOT NULL DEFAULT 0,
    47→  credits INTEGER NOT NULL DEFAULT 0,
    48→  active BOOLEAN NOT NULL DEFAULT true,
    49→  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
    50→);
    51→
    52→-- 6. PLATFORM_CONFIG TABLE (single row)
    53→CREATE TABLE public.platform_config (
    54→  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    55→  max_resumes_per_job INTEGER NOT NULL DEFAULT 10,
    56→  max_file_size_mb INTEGER NOT NULL DEFAULT 5,
    57→  resume_retention_days INTEGER NOT NULL DEFAULT 30,
    58→  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
    59→);
    60→
    61→INSERT INTO public.platform_config (max_resumes_per_job, max_file_size_mb, resume_retention_days)
    62→VALUES (10, 5, 30);
    63→
    64→-- 7. JOBS TABLE
    65→CREATE TABLE public.jobs (
    66→  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    67→  user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL,
    68→  job_description TEXT NOT NULL,
    69→  must_weight INTEGER NOT NULL DEFAULT 50,
    70→  nice_weight INTEGER NOT NULL DEFAULT 30,
    71→  optional_weight INTEGER NOT NULL DEFAULT 20,
    72→  status TEXT NOT NULL DEFAULT 'pending',
    73→  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
    74→);
    75→
    76→-- 8. RESUMES TABLE (with vector column)
    77→CREATE TABLE public.resumes (
    78→  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    79→  job_id UUID REFERENCES public.jobs(id) ON DELETE CASCADE NOT NULL,
    80→  filename TEXT NOT NULL,
    81→  file_path TEXT,
    82→  parsed_text TEXT,
    83→  embedding extensions.vector(1536),
    84→  source TEXT NOT NULL DEFAULT 'upload',
    85→  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
    86→);
    87→
    88→-- 9. RESULTS TABLE
    89→CREATE TABLE public.results (
    90→  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    91→  resume_id UUID REFERENCES public.resumes(id) ON DELETE CASCADE NOT NULL,
    92→  skill_score NUMERIC(5,2) DEFAULT 0,
    93→  experience_score NUMERIC(5,2) DEFAULT 0,
    94→  education_score NUMERIC(5,2) DEFAULT 0,
    95→  overall_score NUMERIC(5,2) DEFAULT 0,
    96→  missing_skills TEXT[] DEFAULT '{}',
    97→  red_flags JSONB DEFAULT '{}',
    98→  summary TEXT,
    99→  interview_questions JSONB DEFAULT '[]',
   100→  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
   101→);
   102→
   103→-- 10. USAGE_LOGS TABLE
   104→CREATE TABLE public.usage_logs (
   105→  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
   106→  user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL,
   107→  job_id UUID REFERENCES public.jobs(id) ON DELETE SET NULL,
   108→  credits_used INTEGER NOT NULL DEFAULT 0,
   109→  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
   110→);
   111→
   112→-- =============================================
   113→-- HELPER FUNCTIONS
   114→-- =============================================
   115→
   116→CREATE OR REPLACE FUNCTION public.has_role(_user_id UUID, _role app_role)
   117→RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
   118→  SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role)
   119→$$;
   120→
   121→CREATE OR REPLACE FUNCTION public.is_job_owner(_user_id UUID, _job_id UUID)
   122→RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
   123→  SELECT EXISTS (SELECT 1 FROM public.jobs WHERE id = _job_id AND user_id = _user_id)
   124→$$;
   125→
   126→CREATE OR REPLACE FUNCTION public.deduct_credits(_user_id UUID, _job_id UUID, _amount INTEGER)
   127→RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
   128→DECLARE current_credits INTEGER;
   129→BEGIN
   130→  SELECT credits INTO current_credits FROM public.profiles WHERE user_id = _user_id FOR UPDATE;
   131→  IF current_credits IS NULL OR current_credits < _amount THEN RETURN FALSE; END IF;
   132→  UPDATE public.profiles SET credits = credits - _amount, updated_at = now() WHERE user_id = _user_id;
   133→  INSERT INTO public.usage_logs (user_id, job_id, credits_used) VALUES (_user_id, _job_id, _amount);
   134→  RETURN TRUE;
   135→END;
   136→$$;
   137→
   138→CREATE OR REPLACE FUNCTION public.update_updated_at_column()
   139→RETURNS TRIGGER LANGUAGE plpgsql SET search_path = public AS $$
   140→BEGIN NEW.updated_at = now(); RETURN NEW; END;
   141→$$;
   142→
   143→-- =============================================
   144→-- TRIGGERS
   145→-- =============================================
   146→
   147→CREATE TRIGGER update_profiles_updated_at BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
   148→CREATE TRIGGER update_platform_config_updated_at BEFORE UPDATE ON public.platform_config FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
   149→
   150→CREATE OR REPLACE FUNCTION public.handle_new_user()
   151→RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
   152→BEGIN
   153→  INSERT INTO public.profiles (user_id, inbox_email) VALUES (NEW.id, encode(gen_random_bytes(8), 'hex') || '@inbound.instantranker.com');
   154→  INSERT INTO public.user_roles (user_id, role) VALUES (NEW.id, 'user');
   155→  RETURN NEW;
   156→END;
   157→$$;
   158→
   159→CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();
   160→
   161→-- =============================================
   162→-- RLS POLICIES
   163→-- =============================================
   164→
   165→ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
   166→ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
   167→ALTER TABLE public.plans ENABLE ROW LEVEL SECURITY;
   168→ALTER TABLE public.credit_packs ENABLE ROW LEVEL SECURITY;
   169→ALTER TABLE public.platform_config ENABLE ROW LEVEL SECURITY;
   170→ALTER TABLE public.jobs ENABLE ROW LEVEL SECURITY;
   171→ALTER TABLE public.resumes ENABLE ROW LEVEL SECURITY;
   172→ALTER TABLE public.results ENABLE ROW LEVEL SECURITY;
   173→ALTER TABLE public.usage_logs ENABLE ROW LEVEL SECURITY;
   174→
   175→CREATE POLICY "Users read own profile" ON public.profiles FOR SELECT TO authenticated USING (user_id = auth.uid());
   176→CREATE POLICY "Users update own profile" ON public.profiles FOR UPDATE TO authenticated USING (user_id = auth.uid());
   177→
   178→CREATE POLICY "Users read own role" ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid() OR public.has_role(auth.uid(), 'admin'));
   179→CREATE POLICY "No self role insert" ON public.user_roles FOR INSERT TO authenticated WITH CHECK (false);
   180→CREATE POLICY "No self role update" ON public.user_roles FOR UPDATE TO authenticated USING (false);
   181→CREATE POLICY "Admin delete roles" ON public.user_roles FOR DELETE TO authenticated USING (public.has_role(auth.uid(), 'admin'));
   182→
   183→CREATE POLICY "Anyone reads plans" ON public.plans FOR SELECT TO authenticated USING (true);
   184→CREATE POLICY "Admin insert plans" ON public.plans FOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(), 'admin'));
   185→CREATE POLICY "Admin update plans" ON public.plans FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin'));
   186→CREATE POLICY "Admin delete plans" ON public.plans FOR DELETE TO authenticated USING (public.has_role(auth.uid(), 'admin'));
   187→
   188→CREATE POLICY "Anyone reads credit packs" ON public.credit_packs FOR SELECT TO authenticated USING (true);
   189→CREATE POLICY "Admin insert credit packs" ON public.credit_packs FOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(), 'admin'));
   190→CREATE POLICY "Admin update credit packs" ON public.credit_packs FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin'));
   191→CREATE POLICY "Admin delete credit packs" ON public.credit_packs FOR DELETE TO authenticated USING (public.has_role(auth.uid(), 'admin'));
   192→
   193→CREATE POLICY "Anyone reads config" ON public.platform_config FOR SELECT TO authenticated USING (true);
   194→CREATE POLICY "Admin update config" ON public.platform_config FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin'));
   195→
   196→CREATE POLICY "Users read own jobs" ON public.jobs FOR SELECT TO authenticated USING (user_id = auth.uid());
   197→CREATE POLICY "Users insert own jobs" ON public.jobs FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid());
   198→CREATE POLICY "Users update own jobs" ON public.jobs FOR UPDATE TO authenticated USING (user_id = auth.uid());
   199→CREATE POLICY "Users delete own jobs" ON public.jobs FOR DELETE TO authenticated USING (user_id = auth.uid());
   200→
   201→CREATE POLICY "Users read own resumes" ON public.resumes FOR SELECT TO authenticated USING (public.is_job_owner(auth.uid(), job_id));
   202→CREATE POLICY "Users insert own resumes" ON public.resumes FOR INSERT TO authenticated WITH CHECK (public.is_job_owner(auth.uid(), job_id));
   203→CREATE POLICY "Users update own resumes" ON public.resumes FOR UPDATE TO authenticated USING (public.is_job_owner(auth.uid(), job_id));
   204→CREATE POLICY "Users delete own resumes" ON public.resumes FOR DELETE TO authenticated USING (public.is_job_owner(auth.uid(), job_id));
   205→
   206→CREATE POLICY "Users read own results" ON public.results FOR SELECT TO authenticated
   207→  USING (EXISTS (SELECT 1 FROM public.resumes r JOIN public.jobs j ON r.job_id = j.id WHERE r.id = results.resume_id AND j.user_id = auth.uid()));
   208→
   209→CREATE POLICY "Admin reads usage logs" ON public.usage_logs FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'));
   210→
   211→-- =============================================
   212→-- STORAGE
   213→-- =============================================
   214→
   215→INSERT INTO storage.buckets (id, name, public) VALUES ('resumes', 'resumes', false);
   216→
   217→CREATE POLICY "Users upload own resumes" ON storage.objects FOR INSERT TO authenticated
   218→  WITH CHECK (bucket_id = 'resumes' AND auth.uid()::text = (storage.foldername(name))[1]);
   219→CREATE POLICY "Users read own resume files" ON storage.objects FOR SELECT TO authenticated
   220→  USING (bucket_id = 'resumes' AND auth.uid()::text = (storage.foldername(name))[1]);
   221→CREATE POLICY "Users delete own resume files" ON storage.objects FOR DELETE TO authenticated
   222→  USING (bucket_id = 'resumes' AND auth.uid()::text = (storage.foldername(name))[1]);
   223→

