     1→import { useState } from "react";
     2→import { useQuery } from "@tanstack/react-query";
     3→import { supabase } from "@/integrations/supabase/client";
     4→import { useAuth } from "@/hooks/useAuth";
     5→import {
     6→  Dialog,
     7→  DialogContent,
     8→  DialogDescription,
     9→  DialogHeader,
    10→  DialogTitle,
    11→  DialogTrigger,
    12→} from "@/components/ui/dialog";
    13→import { Button } from "@/components/ui/button";
    14→import { Badge } from "@/components/ui/badge";
    15→import { toast } from "sonner";
    16→import { Coins, Loader2, ShoppingCart, Sparkles, Crown, Gift } from "lucide-react";
    17→import SubscriptionDialog from "@/components/SubscriptionDialog";
    18→
    19→interface BuyCreditsDialogProps {
    20→  trigger?: React.ReactNode;
    21→}
    22→
    23→const BuyCreditsDialog = ({ trigger }: BuyCreditsDialogProps) => {
    24→  const { user, refreshProfile } = useAuth();
    25→  const [open, setOpen] = useState(false);
    26→  const [buying, setBuying] = useState<string | null>(null);
    27→
    28→  const { data: packs } = useQuery({
    29→    queryKey: ["credit_packs_active"],
    30→    queryFn: async () => {
    31→      const { data, error } = await supabase
    32→        .from("credit_packs")
    33→        .select("*")
    34→        .eq("active", true)
    35→        .order("price");
    36→      if (error) throw error;
    37→      return data;
    38→    },
    39→  });
    40→
    41→  const { data: hasPaidPayments } = useQuery({
    42→    queryKey: ["user_has_paid_payments", user?.id],
    43→    enabled: !!user,
    44→    queryFn: async () => {
    45→      const { count, error } = await supabase
    46→        .from("payments")
    47→        .select("id", { count: "exact", head: true })
    48→        .eq("user_id", user!.id)
    49→        .eq("status", "paid");
    50→      if (error) throw error;
    51→      return (count ?? 0) > 0;
    52→    },
    53→  });
    54→
    55→  const isTrialEligible = hasPaidPayments === false;
    56→
    57→  const visiblePacks = packs?.filter((p: any) => {
    58→    if (p.is_trial && !isTrialEligible) return false;
    59→    return true;
    60→  });
    61→
    62→  const trialPack = visiblePacks?.find((p: any) => p.is_trial);
    63→  const regularPacks = visiblePacks?.filter((p: any) => !p.is_trial);
    64→
    65→  const handleBuy = async (packId: string) => {
    66→    if (!user) return;
    67→    setBuying(packId);
    68→
    69→    try {
    70→      const { data, error } = await supabase.functions.invoke("create-dodo-checkout", {
    71→        body: {
    72→          pack_id: packId,
    73→          return_url: `${window.location.origin}/payment/callback`,
    74→        },
    75→      });
    76→
    77→      if (error) throw error;
    78→
    79→      if (!data?.checkout_url) {
    80→        toast.error(data?.error || "Failed to create checkout session");
    81→        return;
    82→      }
    83→
    84→      // Redirect to Dodo hosted checkout
    85→      window.location.href = data.checkout_url;
    86→    } catch (err: any) {
    87→      toast.error(err.message);
    88→    } finally {
    89→      setBuying(null);
    90→    }
    91→  };
    92→
    93→  return (
    94→    <Dialog open={open} onOpenChange={setOpen}>
    95→      <DialogTrigger asChild>
    96→        {trigger || (
    97→          <Button variant="outline" className="gap-2">
    98→            <ShoppingCart className="h-4 w-4" />
    99→            Buy Credits
   100→          </Button>
   101→        )}
   102→      </DialogTrigger>
   103→      <DialogContent className="sm:max-w-md">
   104→        <DialogHeader>
   105→          <DialogTitle className="flex items-center gap-2">
   106→            <Sparkles className="h-5 w-5 text-primary" />
   107→            Buy Credit Packs
   108→          </DialogTitle>
   109→          <DialogDescription>
   110→            Purchase credits to rank more resumes. Credits never expire.
   111→          </DialogDescription>
   112→        </DialogHeader>
   113→        <div className="space-y-3 pt-2">
   114→          {trialPack && (
   115→            <div className="relative rounded-xl p-[2px] bg-gradient-to-r from-primary via-amber-500 to-primary animate-pulse-slow">
   116→              <div className="rounded-[10px] bg-background p-4">
   117→                <div className="flex items-center gap-2 mb-2">
   118→                  <Gift className="h-5 w-5 text-amber-500" />
   119→                  <Badge className="bg-gradient-to-r from-primary to-amber-500 text-primary-foreground border-0 text-xs">
   120→                    🎁 Welcome Offer
   121→                  </Badge>
   122→                  <Badge variant="outline" className="text-[10px] text-muted-foreground">
   123→                    First purchase only
   124→                  </Badge>
   125→                </div>
   126→                <div className="flex items-center justify-between">
   127→                  <div>
   128→                    <p className="font-semibold text-foreground text-base">{trialPack.name}</p>
   129→                    <div className="flex items-center gap-2 mt-1">
   130→                      <Badge variant="secondary" className="gap-1">
   131→                        <Coins className="h-3 w-3" />
   132→                        {trialPack.credits} credits
   133→                      </Badge>
   134→                    </div>
   135→                    <p className="text-[11px] text-muted-foreground mt-1.5">
   136→                      Try before you commit — this offer won't appear again
   137→                    </p>
   138→                  </div>
   139→                  <Button
   140→                    size="sm"
   141→                    className="bg-gradient-to-r from-primary to-amber-500 hover:from-primary/90 hover:to-amber-500/90 text-primary-foreground font-bold"
   142→                    onClick={() => handleBuy(trialPack.id)}
   143→                    disabled={buying === trialPack.id}
   144→                  >
   145→                    {buying === trialPack.id ? (
   146→                      <Loader2 className="h-4 w-4 animate-spin mr-1" />
   147→                    ) : null}
   148→                    {trialPack.price === 0 ? "Free" : `$${trialPack.price}`}
   149→                  </Button>
   150→                </div>
   151→              </div>
   152→            </div>
   153→          )}
   154→
   155→          {regularPacks?.map((pack: any) => (
   156→            <div
   157→              key={pack.id}
   158→              className="flex items-center justify-between rounded-lg border border-border p-4 hover:bg-accent/50 transition-colors"
   159→            >
   160→              <div>
   161→                <p className="font-medium text-foreground">{pack.name}</p>
   162→                <div className="flex items-center gap-2 mt-1">
   163→                  <Badge variant="secondary" className="gap-1">
   164→                    <Coins className="h-3 w-3" />
   165→                    {pack.credits} credits
   166→                  </Badge>
   167→                </div>
   168→              </div>
   169→              <Button
   170→                size="sm"
   171→                onClick={() => handleBuy(pack.id)}
   172→                disabled={buying === pack.id}
