    79→function tokenize(term: string): string[] {
    80→  return term.toLowerCase().replace(/[^a-z0-9\s+#]/g, ' ').split(/\s+/).filter(t => t.length > 1);
    81→}
    82→
    83→function tokenOverlap(a: string, b: string): number {
    84→  const tokensA = tokenize(a);
    85→  const tokensB = tokenize(b);
    86→  if (tokensA.length === 0 || tokensB.length === 0) return 0;
    87→  const setB = new Set(tokensB);
    88→  const matched = tokensA.filter(t => setB.has(t)).length;
    89→  return matched / Math.max(tokensA.length, tokensB.length);
    90→}
